insert into public.question_options (question_id, label, body, is_correct, position) select me_q.id, v.label, v.body, v.ok, v.pos from me_q, (values ('A', 'OR', false, 1), ('B', 'NOR', true, 2), ('C', 'NAND', false, 3), ('D', 'AND', false, 4)) as v(label, body, ok, pos) where me_q.key = 'N10';
